use vstd::prelude::*;

verus! {
    fn is_sorted(arr: &Vec<i32>) -> (result: bool)
        requires
            arr.len() > 0,
        ensures
            result == (forall|i: int, j: int| 0 <= i < j < arr.len() ==> (arr[i] <= arr[j])),
    {
        let n = arr.len() as int;
        let mut sorted = true;

        // We will check pairs (i, j) with 0 <= i < j < n
        let mut i: int = 0;
        while i < n - 1
            invariant
                0 <= i <= n - 1,
                sorted == (forall|k: int, l: int| 0 <= k < l <= i ==> (arr[k] <= arr[l])),
            decreases n - 1 - i,
        {
            let j: int = i + 1;

            // Check if arr[i] <= arr[j]
            if arr[i] > arr[j] {
                sorted = false;
            }

            i = i + 1;
        }

        sorted
    }
}
